import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;

public class Solve6 {

    public static void main(String[] args) throws IOException {
        PrintWriter writer = new PrintWriter(System.out);
        new Solve6().run(writer);
        writer.flush();
        writer.close();
    }

    public void run(PrintWriter writer) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String inputStr = reader.readLine();
        char[] data = inputStr.toCharArray();
        int countPairs = 0;
        int startIndex = 0;
        int currentIndex = 0;
        while (startIndex < data.length) {
            while (currentIndex < data.length && data[currentIndex] == data[startIndex]) {
                currentIndex++;
            }
            if ((currentIndex - startIndex) % 2 == 0) {
                countPairs++;
            }
            startIndex = currentIndex;
        }
        writer.println(countPairs);
    }
}
